# ---- second round with a FIB that has several TYPE3 nodes per stage ----
def multi_type3_fib():
    import sys, os
    from richfib import mk
    fib = {}
    K = 0x20010db800000000
    # two 64-front forests, each with a TYPE3 root (20 and 15 children)
    for off in (0, 1):
        key = K + off
        for k in range(20 - off * 5):
            fib[(mk(key, [(64, k, 6)], 96), 96)] = 500 + k + off * 100
        for l in range(65, 71):
            fib[(mk(key, [], l), l)] = l
    return fib

