r = run({"cases":[{"ops":[["load", img1]]}]})
assert r['results'][0]['loads'] == [True], 'base image rejected'
print('multi-type3 base accepted; cells', img1['cells'])

def m_bulk_odd(img):
    for s in range(11):
        for r in range(len(img['banks'][s])):
            if getf(img, s, r, 0, 3) == 3:
                b = getf(img, s, r, 127, 22)
                if b >= 2:
                    setf(img, s, r, 127, 22, b - 1); return
    raise Skip()
mut('bulk-base-odd', m_bulk_odd)

def m_bulk_short(img):
    for s in range(11):
        for r in range(len(img['banks'][s])):
            if getf(img, s, r, 0, 3) == 3:
                bm = getf(img, s, r, 63, 64)
                # clear bits until only 3 remain
                cnt = bin(bm).count('1')
                if cnt > 3:
                    keep = 0
                    for bit in range(64):
                        if (bm >> bit) & 1:
                            keep += 1
                            if keep > 3: break
                    nb = bm & ((1 << bit) - 1)
                    setf(img, s, r, 63, 64, nb)
                    return
    raise Skip()
mut('bulk-too-few', m_bulk_short)

def m_child_dup_key(img):
    for s in range(11):
        for r in range(len(img['banks'][s])):
            t = getf(img, s, r, 0, 3)
            if t == 2:
                a = getf(img, s, r, 63, 32)
                setf(img, s, r, 95, 32, a)
                return
    raise Skip()
mut('duplicate-child-key', m_child_dup_key)

def m_ni_pos_too_long(img):
    # set NI bit 63 (l=5) on a depth-12 origin-0 node -> length 17 > 16
    for s in range(11):
        for r in range(len(img['banks'][s])):
            if getf(img, s, r, 0, 3) in (1,2,3):
                b = getf(img, s, r, 25, 16)
                p = int(img['bitmaps'][b], 16)
                if not (p & (1 << 63)):
                    img['bitmaps'][b] = '%016x' % (p | (1 << 63))
                    return
    raise Skip()
mut('ni-position-too-long', m_ni_pos_too_long)

def m_cell_out_of_range(img):
    for s in range(11):
        for r in range(len(img['banks'][s])):
            t = getf(img, s, r, 0, 3)
            if t in (1,2):
                setf(img, s, r, 63, 32, 0x3FFFFF << 10 | (5 << 6)); return
    raise Skip()
mut('child-cell-out-of-range', m_cell_out_of_range)

def m_drop_ni_entry(img):
    if img['nexthops']:
        img['nexthops'].pop()
        return
    raise Skip()
mut('ni-entry-missing', m_drop_ni_entry)

def m_extra_ni_entry(img):
