mut('ni-entry-extra', m_extra_ni_entry)

def m_swap_bulk_children(img):
    # swap two rows that both hold bulk children in the same stage
    for s in range(11):
        rows = [r for r in range(len(img['banks'][s]))]
        if len(rows) >= 3:
            img['banks'][s][1], img['banks'][s][2] = img['banks'][s][2], img['banks'][s][1]
            return
    raise Skip()
mut('bulk-order-swap', m_swap_bulk_children)

